    {
      "obligation_id": "OB-006",
      "strategy": "example",
      "rationale": "Falsifies a reading where the principal's trailing '*' is treated as a wildcard glob (prefix-matching 'alice') instead of being compared as the literal string 'al*', which per the clause must not match 'alice' but must match the literal subject 'al*'.",
      "code": "import impl


def test_principal_glob_star_is_literal_not_wildcard():
    policies = [
        {
            "effect": "ALLOW",
            "principal": "user:al*",
            "action": "*",
            "resource": "*",
        }
    ]

    request_alice = {
        "subject": "alice",
        "roles": [],
        "action": "read",
        "resource": "doc",
    }
    # 'user:al*' must be compared as the literal string 'al*', so it must
    # NOT prefix-match 'alice' -> no ALLOW policy applies -> DENY.
    assert impl.authorize(request_alice, policies) == "DENY"

    request_literal = {
        "subject": "al*",
        "roles": [],
        "action": "read",
        "resource": "doc",
    }
    # The literal string 'al*' as the subject must match the principal
    # 'user:al*' exactly -> ALLOW.
    assert impl.authorize(request_literal, policies) == "ALLOW"
